// GameSessionItem One item of a session. `public` is the client-safe document (an LL question without its key, a scenario or track spec); answer keys and hazard windows are never in it. `reveal` carries hazard windows only for learn and practice items.
type GameSessionItem struct {
	// AssetUrl Signed media URL for this session (clips); it expires with the session
	AssetUrl       *string `json:"asset_url,omitempty"`
	Bytes          *int    `json:"bytes,omitempty"`
	ContentVersion string  `json:"content_version"`

	// ItemRef game-core ItemRef: `<kind>:<id>` with an optional `@<version>` or `:v<n>`, for example `clip:KL-0001@1`, `q:C-LL1-001:v1`, `sd:r1-40-dry`, `track:generic-8@1`. No path separators.
	//
	// Example: clip:KL-0001@1
	ItemRef ItemRef `json:"item_ref"`

	// Kind The ItemRef kind (clip, q, sd, bs, js and track today)
	//
	// Example: clip
	Kind string `json:"kind"`

	// Origin Clips only: how the clip was made (ADR-0013). AI-generated clips carry the AI disclosure in the player.
	Origin    *GameSessionItemOrigin `json:"origin,omitempty"`
	PosterUrl *string                `json:"poster_url,omitempty"`

	// Public Client-safe item document: the content/generated/ll-bank.client.json item for q, the game-core content document for sd, bs, js and track; absent for clips
	Public *map[string]interface{} `json:"public,omitempty"`

	// Reveal Final hazard windows of one clip, sent only for learn and practice items (the clip then counts as seen and is never served in a mock to this subject).
	Reveal *ItemReveal `json:"reveal,omitempty"`
	Sha256 *string     `json:"sha256,omitempty"`

	// SrAltUrl Audio-described still-frame alternative (screen-reader path, EC-18); labelled not the same skill as the timed test
	SrAltUrl *string `json:"sr_alt_url,omitempty"`
}

// GameSessionItemOrigin Clips only: how the clip was made (ADR-0013). AI-generated clips carry the AI disclosure in the player.
type GameSessionItemOrigin string

// GameSessionReplay The replay endpoint's answer - final windows of the session's clips with the analysed facts, for the replay scrubber.
type GameSessionReplay struct {
	Clips []struct {
		// Analysis One clip of a Nazar session as analysed by the score verifier (game-core analyseNazarClips, verifier `analysis.nazar_clips`), in snake_case. Never carries a window.
		Analysis *NazarClipAnalysis `json:"analysis,omitempty"`

		// AssetUrl Fresh signed media URL
		AssetUrl   *string `json:"asset_url,omitempty"`
		DurationMs int     `json:"duration_ms"`

		// ItemRef game-core ItemRef: `<kind>:<id>` with an optional `@<version>` or `:v<n>`, for example `clip:KL-0001@1`, `q:C-LL1-001:v1`, `sd:r1-40-dry`, `track:generic-8@1`. No path separators.
		//
		// Example: clip:KL-0001@1
		ItemRef ItemRef `json:"item_ref"`
		Ordinal int     `json:"ordinal"`

		// Origin How the clip was made (ADR-0013)
		Origin      *GameSessionReplayClipsOrigin `json:"origin,omitempty"`
		SpeedKmhEst *float32                      `json:"speed_kmh_est,omitempty"`
		Windows     []HazardWindow                `json:"windows"`
	} `json:"clips"`
	GameId    GameId                  `json:"game_id"`
	Rule      GameSessionReplayRule   `json:"rule"`
	SessionId openapi_types.UUID      `json:"session_id"`
	Status    GameSessionReplayStatus `json:"status"`
}

