// Plan API-01 plan: the rules engine's Plan exactly as internal/rules produces it (the same JSON
// as the TypeScript mirror packages/rules and the tests/golden snapshots), plus `plan_id`,
// `quote_id` (the stored fee quote, payable through API-19 once a case is opened from the
// plan), `age_band` (canonical band) and `expires_at` (7-day snapshot). Every value carries
// its rule IDs and provenance; rows with `verify_at_rto` show the "verify at your RTO" chip.
type Plan struct {
	Age struct {
		// Band Engine band (under_16, 16_17, 18_19, 20_39, 40_plus); age_band is the canonical one
		Band         string              `json:"band"`
		DobPrecision PlanAgeDobPrecision `json:"dob_precision"`
		YearsMax     int                 `json:"years_max"`
		YearsMin     int                 `json:"years_min"`
	} `json:"age"`
	AgeBand *AgeBand `json:"age_band,omitempty"`

	// AsOf Server IST date the plan was computed on (EC-15)
	AsOf     openapi_types.Date `json:"as_of"`
	Blockers []EngineIssue      `json:"blockers"`

	// Bundles Smart class planner (F-03, MD-105): classes that share one LL now and later LLs for classes possible later (EC-21)
	Bundles []struct {
		BundleNo        int                `json:"bundle_no"`
		Classes         []VehicleClassCode `json:"classes"`
		DlTestUnlock    openapi_types.Date `json:"dl_test_unlock"`
		EarliestLicence openapi_types.Date `json:"earliest_licence"`

		// Fees E-07 as the engine computes it from fees.json (integer paise; never a literal)
		Fees        EngineFeeQuote     `json:"fees"`
		LlExpiresOn openapi_types.Date `json:"ll_expires_on"`
		LlFrom      openapi_types.Date `json:"ll_from"`
		RuleIds     []string           `json:"rule_ids"`
	} `json:"bundles"`
	Classes   []EngineClassResult    `json:"classes"`
	DlTest    map[string]interface{} `json:"dl_test"`
	Documents []struct {
		DocId    string `json:"doc_id"`
		Required bool   `json:"required"`
		RuleId   string `json:"rule_id"`
		Stage    string `json:"stage"`
		TextKey  string `json:"text_key"`
		Verified bool   `json:"verified"`
	} `json:"documents"`
	EarliestDates *struct {
		DlTestUnlock    *openapi_types.Date `json:"dl_test_unlock,omitempty"`
		EarliestLicence *openapi_types.Date `json:"earliest_licence,omitempty"`
		LlExpiresOn     *openapi_types.Date `json:"ll_expires_on,omitempty"`
		LlIssue         *openapi_types.Date `json:"ll_issue,omitempty"`
	} `json:"earliest_dates,omitempty"`
	ExpiresAt time.Time `json:"expires_at"`

	// FamilyModeRequired A learner under 18 uses the plan inside a parent's account (D-13 revised)
	FamilyModeRequired bool                   `json:"family_mode_required"`
	Fees               *EngineFeeQuote        `json:"fees,omitempty"`
	Hpt                map[string]interface{} `json:"hpt"`

	// LlTest EC-10 - online_available false switches the card to "test at the RTO"
	LlTest struct {
		Confidence      *string         `json:"confidence,omitempty"`
		Known           *bool           `json:"known,omitempty"`
		Mode            *PlanLlTestMode `json:"mode,omitempty"`
		OnlineAvailable *bool           `json:"online_available,omitempty"`
		PassCorrect     *int            `json:"pass_correct,omitempty"`
		PassPct         *int            `json:"pass_pct,omitempty"`
		Questions       *int            `json:"questions,omitempty"`
		RuleIds         *[]string       `json:"rule_ids,omitempty"`
		Verified        *bool           `json:"verified,omitempty"`
		Where           *[]string       `json:"where,omitempty"`
	} `json:"ll_test"`
	MaxRtoVisits int `json:"max_rto_visits"`
	Milestones   []struct {
		DueOn  openapi_types.Date `json:"due_on"`
		Id     string             `json:"id"`
		RuleId string             `json:"rule_id"`
	} `json:"milestones"`
	Notices []EngineIssue            `json:"notices"`
	Offices []map[string]interface{} `json:"offices"`
	Paths   []struct {
		LlTestAtRto  bool     `json:"ll_test_at_rto"`
		MaxRtoVisits int      `json:"max_rto_visits"`
		PathId       string   `json:"path_id"`
		Recommended  bool     `json:"recommended"`
		RuleIds      []string `json:"rule_ids"`
	} `json:"paths"`
	PlanId           string             `json:"plan_id"`
	QuoteId          *string            `json:"quote_id,omitempty"`
	RecommendedPath  string             `json:"recommended_path"`
	RequestedClasses []VehicleClassCode `json:"requested_classes"`
	RulePack         struct {
		BaseVersion    *string `json:"base_version,omitempty"`
		ClassesVersion *string `json:"classes_version,omitempty"`
		FeesVersion    *string `json:"fees_version,omitempty"`
		Hash           *string `json:"hash,omitempty"`
		PackId         string  `json:"pack_id"`
		Partial        *bool   `json:"partial,omitempty"`
		Version        string  `json:"version"`
	} `json:"rule_pack"`

	// Saving Shown only "if you would otherwise do them one after the other" (MD-105)
	Saving *struct {
		ApplicationsSaved *int      `json:"applications_saved,omitempty"`
		ClassesOnOneLl    *int      `json:"classes_on_one_ll,omitempty"`
		Confidence        *string   `json:"confidence,omitempty"`
		FeeSavingPaise    *int      `json:"fee_saving_paise,omitempty"`
		NoteKey           *string   `json:"note_key,omitempty"`
		RuleIds           *[]string `json:"rule_ids,omitempty"`
		Verified          *bool     `json:"verified,omitempty"`
		WaitDaysSaved     *int      `json:"wait_days_saved,omitempty"`
	} `json:"saving,omitempty"`

	// State Example: JK
	State StateCode `json:"state"`
	Steps []struct {
		AtRto   bool                `json:"at_rto"`
		Done    bool                `json:"done"`
		DueOn   *openapi_types.Date `json:"due_on,omitempty"`
		Key     string              `json:"key"`
		N       int                 `json:"n"`
		RuleIds []string            `json:"rule_ids"`
		Visit   *int                `json:"visit,omitempty"`
	} `json:"steps"`

	// Trace Every rule ID that fired
	Trace    []string      `json:"trace"`
	Warnings []EngineIssue `json:"warnings"`
}

